float genererBruit3D(vec3 position) {
    vec3 indexInteg = floor(position);
    vec3 fraction = fract(position);
    fraction = fraction * fraction * (3.0 - 2.0 * fraction);

    float h000 = fract(sin(dot(indexInteg + vec3(0.0, 0.0, 0.0), vec3(12.9898, 78.233, 45.5432))) * 43758.5453);
    float h100 = fract(sin(dot(indexInteg + vec3(1.0, 0.0, 0.0), vec3(12.9898, 78.233, 45.5432))) * 43758.5453);
    float h010 = fract(sin(dot(indexInteg + vec3(0.0, 1.0, 0.0), vec3(12.9898, 78.233, 45.5432))) * 43758.5453);
    float h110 = fract(sin(dot(indexInteg + vec3(1.0, 1.0, 0.0), vec3(12.9898, 78.233, 45.5432))) * 43758.5453);

    float h001 = fract(sin(dot(indexInteg + vec3(0.0, 0.0, 1.0), vec3(12.9898, 78.233, 45.5432))) * 43758.5453);
    float h101 = fract(sin(dot(indexInteg + vec3(1.0, 0.0, 1.0), vec3(12.9898, 78.233, 45.5432))) * 43758.5453);
    float h011 = fract(sin(dot(indexInteg + vec3(0.0, 1.0, 1.0), vec3(12.9898, 78.233, 45.5432))) * 43758.5453);
    float h111 = fract(sin(dot(indexInteg + vec3(1.0, 1.0, 1.0), vec3(12.9898, 78.233, 45.5432))) * 43758.5453);

    float planBas = mix(mix(h000, h100, fraction.x), mix(h010, h110, fraction.x), fraction.y);
    float planHaut = mix(mix(h001, h101, fraction.x), mix(h011, h111, fraction.x), fraction.y);

    return mix(planBas, planHaut, fraction.z);
}

float calculerBruitFractal(vec3 position, mat3 matriceRotation) {
    float valeurBruit = 0.0;
    float amplitude = 0.5;

    for (int octal = 0; octal < 4; octal++) {
        valeurBruit += amplitude * genererBruit3D(position);
        position = matriceRotation * position * 2.02;
        amplitude *= 0.5;
    }

    return valeurBruit;
}

void mainImage(out vec4 couleurFragment, vec2 coordFragment) {
    float temps = iTime;
    float distanceMarchee = 0.0;
    float etapeMarchage = 0.0;
    float distanceScene = 0.0;
    float rayonDistance = 0.0;
    float champGravitationnel = 0.0;
    float distanceSoleilCentral = 0.0;
    float distancePlanetes = 0.0;

    vec3 origineRayon = vec3(
        6.0 * sin(temps * 0.3),
        2.5 * cos(temps * 0.15),
        6.0 * cos(temps * 0.3)
    );

    vec3 directionArriere = normalize(-origineRayon);
    vec3 directionDroite = normalize(cross(directionArriere, vec3(0.0, 1.0, 0.0)));
    vec3 directionHaut = cross(directionDroite, directionArriere);

    vec2 uvNormalisees = (coordFragment * 2.0 - iResolution.xy) / iResolution.y;
    vec3 directionViseeLocal = normalize(vec3(uvNormalisees, 1.8));
    vec3 directionRayon = mat3(directionDroite, directionHaut, directionArriere) * directionViseeLocal;

    vec3 positionPlaneteA = vec3(
        1.6 * cos(temps * 1.2),
        0.1 * sin(temps * 1.2),
        1.6 * sin(temps * 1.2)
    );

    vec3 positionPlaneteB = vec3(
        2.5 * cos(temps * 0.7 + 1.5),
        -0.15 * cos(temps * 0.7),
        2.5 * sin(temps * 0.7 + 1.5)
    );

    vec3 positionPlaneteC = vec3(
        3.6 * cos(temps * 0.4 + 3.5),
        0.2 * sin(temps * 0.4),
        3.6 * sin(temps * 0.4 + 3.5)
    );

    vec3 positionCourante;
    mat3 matriceBruit = mat3(
        0.0, 0.8, 0.6,
        -0.8, 0.36, -0.48,
        -0.6, -0.48, 0.64
    );

    couleurFragment = vec4(0.0);

    for (int etape = 0; etape < 100; etape++) {
        etapeMarchage += 1.0;
        positionCourante = origineRayon + distanceMarchee * directionRayon;
        rayonDistance = length(positionCourante);

        champGravitationnel = 1.0 / max(rayonDistance, 0.1) +
                              0.12 / max(length(positionCourante.xz - positionPlaneteA.xz), 0.05) +
                              0.18 / max(length(positionCourante.xz - positionPlaneteB.xz), 0.05) +
                              0.25 / max(length(positionCourante.xz - positionPlaneteC.xz), 0.05);

        distanceSoleilCentral = rayonDistance - 0.75 - 0.1 * calculerBruitFractal(positionCourante * 3.0 - vec3(0.0, temps * 1.5, 0.0), matriceBruit);

        float distancePlaneteA = length(positionCourante - positionPlaneteA) - 0.08;
        float distancePlaneteB = length(positionCourante - positionPlaneteB) - 0.12;
        float distancePlaneteC = length(positionCourante - positionPlaneteC) - 0.15;

        distancePlanetes = min(distancePlaneteA, min(distancePlaneteB, distancePlaneteC));

        float distanceDisqueAccretion = abs(positionCourante.y + champGravitationnel - 1.0) - 0.03;
        distanceScene = min(distanceDisqueAccretion, min(distanceSoleilCentral, distancePlanetes));

        if (distanceSoleilCentral < 0.002) {
            vec3 coulerFeuJaune = vec3(1.0, 0.9, 0.2);
            vec3 couleurFeuRouge = vec3(1.0, 0.1, 0.0);
            float bruitSoleil = calculerBruitFractal(positionCourante * 5.0 + temps * 0.5, matriceBruit);
            couleurFragment.rgb += mix(coulerFeuJaune, couleurFeuRouge, bruitSoleil) * 2.5;
            break;
        }

        if (distancePlanetes < 0.002) {
            if (distancePlaneteA < 0.002) {
                couleurFragment.rgb += vec3(0.8, 0.3, 0.1) * (0.4 + 0.6 * calculerBruitFractal(positionCourante * 15.0, matriceBruit));
            } else if (distancePlaneteB < 0.002) {
                couleurFragment.rgb += vec3(0.2, 0.5, 0.9) * (0.5 + 0.5 * genererBruit3D(positionCourante * 10.0));
            } else {
                couleurFragment.rgb += vec3(0.9, 0.7, 0.4) * (0.6 + 0.4 * sin(positionCourante.y * 30.0));
            }
            break;
        }

        vec2 grilleEspace = abs(fract(positionCourante.xz * 2.0 - 0.5) - 0.5);
        float masqueGrille = smoothstep(0.04, 0.0, min(grilleEspace.x, grilleEspace.y));
        float masqueMiroirHeight = smoothstep(0.15, 0.0, abs(positionCourante.y + champGravitationnel - 1.0));
        float masqueAttenuationDisque = smoothstep(9.0, 0.5, rayonDistance) * 0.4;

        vec3 couleurPoussiereChaude = vec3(1.0, 0.4, 0.1);
        vec3 couleurPoussiereFroide = vec3(0.15, 0.45, 1.0);
        float melangeRayon = clamp((rayonDistance - 1.2) * 0.4, 0.0, 1.0);
        vec3 couleurFondVolumetrique = mix(couleurPoussiereChaude, couleurPoussiereFroide, melangeRayon);

        float intensiteLumiereVolumetrique = (0.0025 + 0.0006 / (distanceScene * distanceScene + 0.0015)) * exp(-rayonDistance * 0.3);

        couleurFragment.rgb += intensiteLumiereVolumetrique * couleurFondVolumetrique +
                               vec3(0.0, 0.8, 1.0) * (masqueGrille * masqueMiroirHeight * masqueAttenuationDisque);

        distanceMarchee += max(distanceScene, 0.006);
    }

    couleurFragment.rgb = couleurFragment.rgb / (1.0 + couleurFragment.rgb);
    couleurFragment = pow(couleurFragment, vec4(0.85));
}
